import { MODULE_ID } from '../constants.js';
import { escapeHTML, localize, sluggify } from '../helpers/utility.js';
import { findSpellUuid, getSpellIndex } from './spellIndex.js';

let innateData = null;

/** Innate spells granted by feats and heritages, generated by scripts/build-innate-spells.mjs */
export const loadInnateData = async () => {
  if (innateData) return innateData;
  try {
    innateData = await foundry.utils.fetchJsonWithTimeout(`modules/${MODULE_ID}/src/data/innateSpells.json`);
  } catch (error) {
    console.error(`${MODULE_ID} | Failed to load innate spell data`, error);
    innateData = { grants: {}, spells: {} };
  }
  return innateData;
};

/** For tests: use data loaded some other way */
export const setInnateData = (data) => {
  innateData = data;
};

const slugOf = (item) => item.slug ?? sluggify(item.name);
const selections = (item) => item.flags?.[game.system.id]?.rulesSelections ?? {};

/**
 * The spells one grant gives: `{ fixed, options, count }`, each spell as `{ uuid, rank, heighten }`.
 * Null when the module can't tell (the spell chosen in the system's prompt is missing, say).
 * @param {Item} item the feat or heritage on the actor
 * @param {object} grant from the generated data
 * @param {object[]} spellIndex
 */
export const resolveInnateGrant = (item, grant, spellIndex) => {
  const withCasting = (uuid) => ({ uuid, rank: grant.rank ?? null, heighten: grant.heighten ?? null });
  switch (grant.kind) {
    case 'linked': {
      const spells = (grant.spells ?? []).map((s) => ({ uuid: s.uuid, rank: s.rank ?? null, heighten: s.heighten ?? null }));
      return grant.choose
        ? { fixed: [], options: spells, count: grant.choose }
        : { fixed: spells, options: [], count: 0 };
    }
    case 'chosen': {
      const value = selections(item)[grant.flag];
      if (typeof value !== 'string' || !value) return null;
      const uuid = grant.slugs ? findSpellUuid(spellIndex, sluggify(value)) : value;
      return uuid ? { fixed: [withCasting(uuid)], options: [], count: 0 } : null;
    }
    case 'list': {
      const { tradition, cantrip } = grant.filter ?? {};
      const options = spellIndex
        .filter((s) => s.rarity === 'common' && (!cantrip || s.cantrip) && (!tradition || s.traditions.includes(tradition)))
        .map((s) => withCasting(s.uuid));
      return options.length ? { fixed: [], options, count: 1 } : null;
    }
    default:
      return null;
  }
};

/** The rank an innate spell is cast at: the grant's rank, or half the level for "heightened to half your level" */
export const innateRank = (spell, base, level) => {
  if (spell.heighten === 'half') return Math.max(base, Math.ceil(level / 2));
  return Math.max(base, spell.rank ?? base);
};

/** How often it can be cast, for the dialog */
const usesLabel = (grant) => {
  if (grant.atWill) return localize('innate.atWill');
  if (grant.perDay) return localize('innate.perDay', { count: grant.perDay });
  return null;
};

/**
 * Innate spells the new items give, grouped by grant, in the shape of the focus spell dialog's groups.
 * Spells the actor already has as innate spells are left out.
 */
export const innateGrantsFor = async (actor, items) => {
  const [data, spellIndex] = await Promise.all([loadInnateData(), getSpellIndex()]);
  const byUuid = new Map(spellIndex.map((s) => [s.uuid, s]));
  const innateEntries = new Set(
    actor.itemTypes.spellcastingEntry.filter((e) => e.system?.prepared?.value === 'innate').map((e) => e.id)
  );
  const owned = new Set(
    actor.itemTypes.spell.filter((s) => innateEntries.has(s.system?.location?.value)).map((s) => s.sourceId)
  );
  const groups = [];
  for (const item of items) {
    if (!['feat', 'heritage'].includes(item.type)) continue;
    const entry = data.grants?.[slugOf(item)];
    if (!entry) continue;
    entry.grants.forEach((grant, i) => {
      const resolved = resolveInnateGrant(item, grant, spellIndex);
      if (!resolved) return;
      const fresh = (list) => list.filter((s) => !owned.has(s.uuid) && (byUuid.has(s.uuid) || data.spells?.[s.uuid]));
      const fixed = fresh(resolved.fixed);
      const options = fresh(resolved.options);
      if (!fixed.length && !options.length) return;
      const spells = new Map([...fixed, ...options].map((s) => [s.uuid, s]));
      const uses = usesLabel(grant);
      const labels = Object.fromEntries(
        [...spells.keys()].map((uuid) => {
          const known = byUuid.get(uuid) ?? data.spells[uuid];
          const base = known?.rank ?? 1;
          const rank = known?.cantrip
            ? localize('spells.cantrip')
            : localize('spells.rankShort', { rank: innateRank(spells.get(uuid), base, actor.level) });
          return [uuid, `${escapeHTML(known?.name ?? uuid)} <span class="lvl-focus-rank">${rank}</span>`];
        })
      );
      groups.push({
        kind: 'innate',
        key: `${item.id}-innate-${i}`,
        source: item.name,
        // Read from the wording: the dialog shows the sentence and asks the player to check it
        grant: { confidence: 'heuristic', note: grant.note },
        tag: [localize('innate.tag'), uses].filter(Boolean).join(' · '),
        fixed: fixed.map((s) => s.uuid),
        options: options.map((s) => s.uuid),
        count: Math.min(resolved.count, options.length),
        labels,
        spells,
        perDay: grant.perDay ?? null,
        tradition: grant.tradition ?? null,
        attribute: 'cha'
      });
    });
  }
  return groups;
};

/**
 * Add the chosen innate spells, each into an innate entry of its tradition (an existing one, or a new
 * one), at the rank and with the daily uses the grant names. Returns the created items.
 */
export const addInnateSpells = async (actor, choices) => {
  const created = [];
  const entries = new Map(
    actor.itemTypes.spellcastingEntry
      .filter((e) => e.system?.prepared?.value === 'innate')
      .map((e) => [e.system?.tradition?.value ?? '', e])
  );
  for (const { group, uuids, tradition } of choices) {
    if (!uuids.length) continue;
    let entry = entries.get(tradition ?? '');
    if (!entry) {
      const traditionName = tradition ? game.i18n.localize(CONFIG.PF2E.magicTraditions?.[tradition] ?? tradition) : '';
      [entry] = await actor.createEmbeddedDocuments('Item', [
        {
          type: 'spellcastingEntry',
          name: localize('innate.entryName', { tradition: traditionName }).trim(),
          system: {
            ability: { value: group.attribute },
            tradition: { value: tradition ?? '' },
            prepared: { value: 'innate', flexible: false },
            proficiency: { slug: '', value: 1 },
            showSlotlessLevels: { value: false }
          },
          flags: { [MODULE_ID]: { innateEntry: true } }
        }
      ]);
      created.push(entry);
      entries.set(tradition ?? '', entry);
    }
    const sources = await Promise.all(
      uuids.map(async (uuid) => {
        const doc = await fromUuid(uuid);
        if (!doc) return null;
        const source = doc.toObject();
        delete source._id;
        delete source.folder;
        delete source.sort;
        delete source.ownership;
        foundry.utils.setProperty(source, '_stats.compendiumSource', doc.uuid);
        const location = { value: entry.id };
        if (!doc.isCantrip) {
          const base = doc.baseRank ?? doc.system?.level?.value ?? 1;
          const rank = innateRank(group.spells.get(uuid) ?? {}, base, actor.level);
          if (rank > base) location.heightenedLevel = rank;
          if (group.perDay) location.uses = { value: group.perDay, max: group.perDay };
        }
        source.system.location = location;
        return source;
      })
    );
    created.push(...(await actor.createEmbeddedDocuments('Item', sources.filter(Boolean))));
  }
  return created;
};
